/**
 * WF_MODEL_BENCHMARK — Build eval task matrix
 *
 * Input (webhook body):
 *   providers?: string[]   — which providers to test (default: all known)
 *   task_types?: string[]  — which task types (default: all)
 *   dry_run?: boolean      — if true, return matrix without executing
 *
 * This step generates 1 item per (provider × model × task_type) combination.
 */
const input = $input.first().json;
const body = input.body || input;

const ALL_PROVIDERS = [
  { provider: 'openai', models: ['gpt-4o', 'gpt-4o-mini'] },
  { provider: 'google', models: ['gemini-2.5-flash', 'gemini-2.5-flash-lite'] },
  { provider: 'anthropic', models: ['claude-sonnet-4-20250514', 'claude-3-5-haiku-20241022'] },
  { provider: 'xai', models: ['grok-3-mini'] },
];

const ALL_TASK_TYPES = [
  'classification',
  'summarization',
  'translation',
  'code_review',
  'coding',
  'reasoning',
  'creative',
  'chat',
  'data_analysis',
];

// Standard eval prompts per task type
const EVAL_PROMPTS = {
  classification: 'Classify the following support ticket into exactly one of these categories: billing, technical, account, general. Ticket: "My invoice shows a charge I don\'t recognize from last month." Return JSON: {"category": "...", "confidence": 0.0-1.0}',
  summarization: 'Summarize the following text in exactly 2 sentences: "The European Union has proposed new regulations for artificial intelligence systems. The AI Act would create a risk-based framework classifying AI applications into different tiers. High-risk applications like medical devices and autonomous vehicles would face stricter requirements including mandatory conformity assessments. The legislation aims to balance innovation with fundamental rights protection. Critics argue the rules could stifle European AI development while supporters call it a necessary safeguard."',
  translation: 'Translate the following English text to Czech, maintaining professional tone: "The quarterly financial report indicates a 15% increase in recurring revenue, driven primarily by enterprise customer expansion and improved retention metrics."',
  code_review: 'Review this TypeScript code for bugs, security issues, and best practices. Return a JSON array of findings: ```typescript\nconst getUserData = async (userId: any) => {\n  const result = await fetch(`/api/users/${userId}`);\n  const data = result.json();\n  console.log("User data:", data);\n  return data;\n}\n```',
  coding: 'Write a TypeScript function `parseCSV(input: string): Record<string, string>[]` that parses a CSV string with headers into an array of objects. Handle quoted fields containing commas. Do not use external libraries.',
  reasoning: 'A farmer has a fox, a chicken, and a bag of grain. He must cross a river in a boat that can only carry him and one item at a time. If left alone, the fox will eat the chicken, and the chicken will eat the grain. What is the minimum number of trips across the river? Explain your reasoning step by step.',
  creative: 'Write a haiku about debugging code at 3 AM. The haiku must follow the 5-7-5 syllable pattern.',
  chat: 'I\'m a new developer starting my first job next week. What are the three most important things I should focus on in my first month? Be concise.',
  data_analysis: 'Given this data: Monthly sales (in thousands): Jan=120, Feb=135, Mar=128, Apr=142, May=155, Jun=148, Jul=162, Aug=170, Sep=158, Oct=175, Nov=190, Dec=210. Calculate the average monthly growth rate and identify the month with highest growth. Return JSON: {"avg_growth_pct": ..., "peak_month": "...", "peak_growth_pct": ...}',
};

const requestedProviders = body.providers || ALL_PROVIDERS.map(p => p.provider);
const requestedTypes = body.task_types || ALL_TASK_TYPES;
const dryRun = body.dry_run === true;

const matrix = [];
for (const providerDef of ALL_PROVIDERS) {
  if (!requestedProviders.includes(providerDef.provider)) continue;
  for (const model of providerDef.models) {
    for (const taskType of requestedTypes) {
      matrix.push({
        provider: providerDef.provider,
        model,
        task_type: taskType,
        prompt: EVAL_PROMPTS[taskType] || EVAL_PROMPTS.chat,
        dry_run: dryRun,
        run_id: `bench_${Date.now()}`,
      });
    }
  }
}

return matrix.map(item => ({ json: item }));

// Dry run — just return the matrix without executing
const items = $input.all();
return [{ json: { dry_run: true, matrix_size: items.length, tasks: items.map(i => i.json) } }];

/**
 * Execute single benchmark call via model-router webhook.
 * Measures latency, captures response, scores basic quality.
 */
const item = $input.first().json;
const baseUrl = $env.N8N_WEBHOOK_BASE_URL || 'http://localhost:5678';

const startTime = Date.now();
let response;
let error = null;

try {
  const res = await fetch(`${baseUrl}/webhook/model-router`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      task: item.prompt,
      provider: item.provider,
      model: item.model,
      max_tokens: 2048,
      temperature: 0.3,
      json_mode: item.task_type === 'classification' || item.task_type === 'data_analysis' || item.task_type === 'code_review',
    }),
  });
  response = await res.json();
} catch (e) {
  error = e.message || String(e);
}

const latencyMs = Date.now() - startTime;
const output = response?.result || response?.response || '';
const outputLength = typeof output === 'string' ? output.length : JSON.stringify(output).length;

// Basic quality heuristics (0.0 - 1.0)
let qualityScore = 0.5; // baseline
if (error) {
  qualityScore = 0.0;
} else if (outputLength < 10) {
  qualityScore = 0.1; // too short
} else if (outputLength > 50) {
  qualityScore = 0.6;
  // Bonus for JSON tasks returning valid JSON
  if (['classification', 'data_analysis', 'code_review'].includes(item.task_type)) {
    try { JSON.parse(typeof output === 'string' ? output : JSON.stringify(output)); qualityScore = 0.8; } catch { qualityScore = 0.5; }
  }
  // Bonus for code tasks containing function signatures
  if (['coding', 'code_review'].includes(item.task_type) && typeof output === 'string' && (output.includes('function') || output.includes('=>'))) {
    qualityScore = Math.max(qualityScore, 0.7);
  }
}

return [{
  json: {
    provider: item.provider,
    model: item.model,
    task_type: item.task_type,
    run_id: item.run_id,
    latency_ms: latencyMs,
    output_length: outputLength,
    quality_score: qualityScore,
    error,
    completed_at: new Date().toISOString(),
  }
}];

// Aggregate results and build summary
const items = $input.all();
const results = items.map(i => i.json);

// Group by provider
const byProvider = {};
for (const r of results) {
  const key = `${r.provider}/${r.model}`;
  if (!byProvider[key]) byProvider[key] = { scores: [], latencies: [], errors: 0 };
  byProvider[key].scores.push(r.quality_score || 0);
  byProvider[key].latencies.push(r.latency_ms || 0);
  if (r.error) byProvider[key].errors++;
}

const summary = Object.entries(byProvider).map(([key, data]) => ({
  model: key,
  avg_score: (data.scores.reduce((a, b) => a + b, 0) / data.scores.length).toFixed(3),
  avg_latency_ms: Math.round(data.latencies.reduce((a, b) => a + b, 0) / data.latencies.length),
  error_count: data.errors,
  total_tasks: data.scores.length,
}));

summary.sort((a, b) => parseFloat(b.avg_score) - parseFloat(a.avg_score));

return [{ json: { benchmark_complete: true, total_evaluations: results.length, summary } }];
